L6_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "우선, 이번 사태의 최우선 사항은 아시다시피 거대 우주선에 관한 정보입니다."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "まず今回の事態の最優先事項は、皆さんも知ってのとおり、巨大宇宙船に関する情報の入手です。"
L6_1.m_Talk_ENG = "As you know, our top priority is gathering information on the massive spaceship."
