L9_1.m_CutScenID = 592
L9_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_Talk_KOREA = "샤레이드와 로터스의 관리 경계 구역에 거대한 우주선이 나타났죠."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "シャレードとロータスの管理警戒区域に、巨大宇宙船が現れました。"
L9_1.m_Talk_ENG = "A gigantic spaceship appeared in the Charade-Lotus perimeter zone."
L9_1.m_Talk_TWN = "在查雷德和洛德斯的管理邊界區域出現了一艘巨大的太空船。"
L9_1.m_Talk_SCN = "在查雷德和洛德斯的管理边界区域出现了一艘巨大的宇宙飞船。"
L9_1.m_Talk_DEU = "A gigantic spaceship appeared in the Charade-Lotus perimeter zone."
L9_1.m_Talk_FRA = "A gigantic spaceship appeared in the Charade-Lotus perimeter zone."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP13_ACT2_STAGE1_START@7#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 592
L10_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L10_1.m_Talk_KOREA = "이 우주선의 정체는 코핀 오브 릴리스. 통칭, 고철 더미의 모선이었습니다."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "この宇宙船の正体はコフィン・オブ・リリス。通称、鉄くずの母船でした。"
L10_1.m_Talk_ENG = "It has been identified as the Coffin of Lilith. It's commonly referred to as the mothership of Scraps."
L10_1.m_Talk_TWN = "這艘太空船的真面目是科芬·莉莉絲，通稱，廢鐵堆的母艦。"
L10_1.m_Talk_SCN = "这艘宇宙飞船的真面目是科芬·莉莉丝，通称，废铁堆的母舰。"
L10_1.m_Talk_DEU = "It has been identified as the Coffin of Lilith. It's commonly referred to as the mothership of Scraps."
L10_1.m_Talk_FRA = "It has been identified as the Coffin of Lilith. It's commonly referred to as the mothership of Scraps."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP13_ACT2_STAGE1_START@8#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 592
L11_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L11_1.m_Talk_KOREA = "현재 모선은 어떠한 움직임도 보이지 않은 채, 그저 허공에 떠있을 뿐입니다만……."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "現在、母船は動きを見せず、ただ宙に浮いているだけですが……"
L11_1.m_Talk_ENG = "At present, the mothership remains suspended in the air, showing no signs of activity."
L11_1.m_Talk_TWN = "目前母艦沒有任何動靜，只是漂浮在空中……"
L11_1.m_Talk_SCN = "目前母舰没有任何动静，只是漂浮在空中……"
L11_1.m_Talk_DEU = "At present, the mothership remains suspended in the air, showing no signs of activity."
L11_1.m_Talk_FRA = "At present, the mothership remains suspended in the air, showing no signs of activity."
