L13_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "고철 더미는 철저하게 정해진 기동 목적에 따라 움직이는 마왕."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "鉄くずは定められた起動目的に徹底的に従って動く魔王。"
L13_1.m_Talk_ENG = "However, Scraps is a Demon Lord that moves with precise intent and purpose."
L13_1.m_Talk_TWN = "廢鐵堆是嚴格按照既定機動目的行動的魔王。"
L13_1.m_Talk_SCN = "废铁堆是严格按照既定机动目的行动的魔王。"
L13_1.m_Talk_DEU = "However, Scraps is a Demon Lord that moves with precise intent and purpose."
L13_1.m_Talk_FRA = "However, Scraps is a Demon Lord that moves with precise intent and purpose."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP13_ACT2_STAGE1_START@10#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 592
L14_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "따라서 녀석이 아무 행동도 취하지 않는 데에는 분명히 그만한 이유가 있을 겁니다."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "よって、やつが何の動きも見せないことには、相応の理由があるはずです。"
L14_1.m_Talk_ENG = "Which means her inaction is deliberate and likely meaningful."
L14_1.m_Talk_TWN = "因此，那傢伙什麼都不做肯定是有原因的。"
L14_1.m_Talk_SCN = "因此，那家伙什么都不做肯定是有原因的。"
L14_1.m_Talk_DEU = "Which means her inaction is deliberate and likely meaningful."
L14_1.m_Talk_FRA = "Which means her inaction is deliberate and likely meaningful."
