L18_1.m_CharStrID = "GSWORD_ADMIN_ReinforcedB_NULL"
L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "어쩌면 고철 더미의 목적은 거점의 방어가 아닐까?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "もしかしたら、鉄くずの目的は拠点の防御ではないかしら。"
