L19_1.m_Pos = "L"
L19_1.m_Talk_KOREA = "지난 정찰에서 우주선에 접근하니까, 갑자기 상당수의 모더레이터가 차원 도약해 왔거든."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "前回の偵察の時、宇宙船に接近したら結構な数のモデレーターが突然次元跳躍してきたの。"
