L21_1.m_Talk_JPN = "一理ある話ですね。ですが現時点ではまだ断言できません。"
L21_1.m_Talk_ENG = "That's a valid theory. However, it's still too early to draw any conclusions."
L21_1.m_Talk_TWN = "說得有道理，但是現在下結論還為時過早。"
L21_1.m_Talk_SCN = "说得有道理，但是现在下结论还为时过早。"
L21_1.m_Talk_DEU = "That's a valid theory. However, it's still too early to draw any conclusions."
L21_1.m_Talk_FRA = "That's a valid theory. However, it's still too early to draw any conclusions."
