L22_1.m_Talk_KOREA = "어쩌면 고철 더미 또한 그곳에서 무언가를 찾고 있는 것일지도 모르니까요."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "もしかしたら鉄くずも、あそこで何かを探している可能性がありますからね。"
L22_1.m_Talk_ENG = "It's also possible that Scraps is looking for something in that area."
