L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "어쨌든 분명한 건, 우주에 있던 마왕이 지상으로 내려올만한 원인이 있다는 거다."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "とにかくはっきりしていることは、宇宙にいた魔王が地上に降りたくなる何らかの原因があるということだ。"
L24_1.m_Talk_ENG = "What is clear is that a Demon Lord who had remained in space has now descended to Earth. And there must be a reason for that."
L24_1.m_Talk_TWN = "不管怎樣，顯然宇宙中的魔王有理由降臨到地上。"
L24_1.m_Talk_SCN = "不管怎样，显然宇宙中的魔王有理由降临到地上。"
L24_1.m_Talk_DEU = "What is clear is that a Demon Lord who had remained in space has now descended to Earth. And there must be a reason for that."
L24_1.m_Talk_FRA = "What is clear is that a Demon Lord who had remained in space has now descended to Earth. And there must be a reason for that."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT2_STAGE1_START@17#Talk"
