L25_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "그렇다면 우리의 최우선 목표는 그 원인을 파악 및 확보하는 것이겠지."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "とすれば、私たちの最優先目標はその原因の把握および確保となるだろう。"
L25_1.m_Talk_ENG = "Which means, our top priority is to identify and secure that reason."
L25_1.m_Talk_TWN = "那麼我們的首要目標就是查明並掌握原因。"
L25_1.m_Talk_SCN = "那么我们的首要目标就是查明并掌握原因。"
L25_1.m_Talk_DEU = "Which means, our top priority is to identify and secure that reason."
L25_1.m_Talk_FRA = "Which means, our top priority is to identify and secure that reason."
