L24_1 = "USER_ADMIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "하지만 기록에 따르면, 노엘 양은 이미 20년 전, 전쟁으로 인해 죽은 소녀라네."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "しかし記録によると、ノエル君はすでに20年前、戦争で命を落としているらしい。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But the records say she died in a war twenty years ago."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但是根據記錄，洛艾兒已經在20年前的戰爭中去世了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "但是根据记录，诺艾尔小姐已经在20年前的战争中去世了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "But the records say she died in a war twenty years ago."
L23_1.m_Talk_DEU = L24_1
L24_1 = "But the records say she died in a war twenty years ago."
L23_1.m_Talk_FRA = L24_1
