L26_1 = "There's only one explanation for this contradiction."
L25_1.m_Talk_ENG = L26_1
L26_1 = "要彌合這兩條資訊的差距，只有一個辦法。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "要弥合这两条信息的差距，只有一个办法。"
