L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "아마도 그녀의 목적은 또 다시 인간을 <color=#ffd34c>시험</color>하려는 것이겠지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "おそらく彼女の目的は、また人間を<color=#ffd34c>試す</color>ことだろう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Most likely, her goal is once again to put humanity to the <color=#ffd34c>test</color>."
L4_1.m_Talk_ENG = L5_1
L5_1 = "也許她的目的是再次對人類進行 <color=#ffd34c>試驗</color>。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "也许她的目的是再次对人类进行 <color=#ffd34c>试验</color>。"
