L7_1.m_Pos = "C"
L8_1 = "고철 더미의 등장과 스완의 행방. 그리고 노엘 양의 존재는 한 가지 결론으로 귀결됩니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "鉄くずの登場とスワンの行方。そしてノエルさんの存在は1つの結論へ収束します。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The appearance of Scraps, Swan's whereabouts, and the existence of Noelle all point to a single conclusion."
L7_1.m_Talk_ENG = L8_1
L8_1 = "廢鐵堆的出現，史旺的行蹤，還有洛艾兒的存在，都導向了一個結論——"
L7_1.m_Talk_TWN = L8_1
L8_1 = "废铁堆的出现，斯旺的行踪，还有诺艾尔小姐的存在，都导向了一个结论——"
L7_1.m_Talk_SCN = L8_1
L8_1 = "The appearance of Scraps, Swan's whereabouts, and the existence of Noelle all point to a single conclusion."
L7_1.m_Talk_DEU = L8_1
L8_1 = "The appearance of Scraps, Swan's whereabouts, and the existence of Noelle all point to a single conclusion."
L7_1.m_Talk_FRA = L8_1
