L8_1.m_Pos = "C"
L9_1 = "샤레이드, 로터스 관리 경계 구역에서 어떠한 현실 개변이 발생했다는 것."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "シャレード、ロータスの管理警戒区域でなんらかの現実改変が発生したということ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "A change in reality occurred in the Charade-Lotus perimeter zone."
L8_1.m_Talk_ENG = L9_1
L9_1 = "查雷德，洛德斯管理的警戒區域發生了某種現實變更。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "查雷德，洛德斯管理的警戒区域发生了某种现实变更。"
