L9_1 = "A change in reality occurred in the Charade-Lotus perimeter zone."
L8_1.m_Talk_DEU = L9_1
L9_1 = "A change in reality occurred in the Charade-Lotus perimeter zone."
L8_1.m_Talk_FRA = L9_1
