L12_1 = "착각하지 마라, 신입. 나 역시 정보 말소에 대해 모르는 게 아니니까."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "勘違いするな、新人。私とて情報抹消のことを知らないわけではない。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Don't fool yourself, rookie. It's not like I don't know about information erasure."
L11_1.m_Talk_ENG = L12_1
L12_1 = "別誤會，新人。我對資訊抹消也不是一無所知。"
