L16_1.m_Pos = "L"
L17_1 = "그래. 구 관리국 시절에도 적지 않은 전우들이 정보가 말소당해, 모두에게 잊혀 버렸다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ああ。旧管理局の頃も、情報を抹消され、皆から忘れ去られた戦友は少なくなかった。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Yeah. Back in those days, we lost a lot of comrades to information erasure."
L16_1.m_Talk_ENG = L17_1
L17_1 = "是啊。在舊管理局時期，也有不少戰友的資訊被抹消，大家都忘記了他們。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "是啊。在旧管理局时期，也有不少战友的信息被抹消，大家都忘记了他们。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Yeah. Back in those days, we lost a lot of comrades to information erasure."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Yeah. Back in those days, we lost a lot of comrades to information erasure."
L16_1.m_Talk_FRA = L17_1
