L18_1 = "EP13_ACT2_STAGE1_START@112#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 168
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 592
