L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L17_1.m_Pos = "L"
L18_1 = "그 현상에 당하면, 대부분은 피해자가 있었는지조차 파악하기 힘들뿐더러……."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "その現象にやられると、被害者が存在していたかすら把握しづらい上に……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Once it takes hold, it's almost impossible to even recognize that someone's gone."
L17_1.m_Talk_ENG = L18_1
L18_1 = "如果遭遇那種現象，大多數情況下甚至很難確定是否有受害者……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "如果遭遇那种现象，大多数情况下甚至很难确定是否有受害者……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Once it takes hold, it's almost impossible to even recognize that someone's gone."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Once it takes hold, it's almost impossible to even recognize that someone's gone."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP13_ACT2_STAGE1_START@113#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 169
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 592
L18_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
