L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L18_1.m_Pos = "L"
L19_1 = "간신히 정보의 모순점을 발견하더라도, 그저 녀석이 존재했었다는 흔적에 다다를 뿐이야."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "何とか情報の矛盾点を見つけたとしても、せいぜいそいつが存在していたという痕跡に辿り着くだけだった。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And even if you do notice a gap in the information, all you find is a trace. Basically a ghost of someone who might have existed."
L18_1.m_Talk_ENG = L19_1
L19_1 = "即使勉強發現了資訊的矛盾點，也只能找到那些傢伙曾經存在的痕跡而已。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "即使勉强发现了信息的矛盾点，也只能找到那些家伙曾经存在的痕迹而已。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "And even if you do notice a gap in the information, all you find is a trace. Basically a ghost of someone who might have existed."
L18_1.m_Talk_DEU = L19_1
L19_1 = "And even if you do notice a gap in the information, all you find is a trace. Basically a ghost of someone who might have existed."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP13_ACT2_STAGE1_START@114#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 170
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 592
L19_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
