L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L19_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L19_1.m_Pos = "L"
L20_1 = "네 케이스는 어디까지나 예외다. 보통은 녀석의 이름도, 얼굴조차도 기억하지 못해."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "お前のようなケースは稀なんだ。通常は抹消された者の名前も、顔すらも思い出せない。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Your case is a rare one. Usually, not even a name or face remains in memory."
L19_1.m_Talk_ENG = L20_1
L20_1 = "你的情況只是個例外。通常情況下，我連那些傢伙的名字和臉都記不住。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "你的情况只是个例外。通常情况下，我连那些家伙的名字和脸都记不住。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Your case is a rare one. Usually, not even a name or face remains in memory."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Your case is a rare one. Usually, not even a name or face remains in memory."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP13_ACT2_STAGE1_START@115#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 171
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 592
L20_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
