L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L20_1.m_Pos = "L"
L21_1 = "그저 마음속에 잔상처럼, 흐릿한 데자뷰만이 평생을 따라다닐 뿐이지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "心の中に残像のように、うっすらとしたデジャヴが一生付き纏うだけ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "All that's left is a faint afterimage, a lingering deja vu that haunts you for life."
L20_1.m_Talk_ENG = L21_1
L21_1 = "就像心中的殘像，模糊的既視感會伴隨一生。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "就像心中的残像，模糊的既视感会伴随一生。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "All that's left is a faint afterimage, a lingering deja vu that haunts you for life."
L20_1.m_Talk_DEU = L21_1
L21_1 = "All that's left is a faint afterimage, a lingering deja vu that haunts you for life."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP13_ACT2_STAGE1_START@116#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 172
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 592
L21_1.m_CutScenStrID = "EP13_ACT2_STAGE1_START"
