L22_1 = "UNIT_DESPAIR"
L21_1.m_Face = L22_1
L21_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L21_1.m_Pos = "L"
L22_1 = "어쩌면 그건… 당한 녀석도, 남은 녀석들에게도 죽음보다 더한 상처를 남길지도 몰라."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "もしかするとそれは……消された者、残された者の両者に、死よりも酷な傷を残すことになるのかもしれん。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "And maybe... that kind of loss leaves a deeper scar than death, for both the one erased and the ones left behind."
L21_1.m_Talk_ENG = L22_1
L22_1 = "或許那東西……對受害者和倖存者來說，都留下了比死亡更深的傷痕。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "或许那东西……对受害者和幸存者来说，都留下了比死亡更深的伤痕。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "And maybe... that kind of loss leaves a deeper scar than death, for both the one erased and the ones left behind."
L21_1.m_Talk_DEU = L22_1
L22_1 = "And maybe... that kind of loss leaves a deeper scar than death, for both the one erased and the ones left behind."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
